//! Our own bitmap font: hand written 5x7 glyphs, integer scaling.
//!
//! Data lives in [`crate::font_data`] (generated by `tools/genfont.py`).
//! Scaling is *integer*: a 16 px font is drawn at scale 2 (10×14 px cell).
//! Layout asks this module for metrics, so line boxes always match what the
//! rasterizer will paint — no half-covered glyph rows.

use crate::font_data::{
    ASCENT_ROWS, ASCII, ASCII_START, DESCENT_ROWS, EXTRA, GLYPH_HEIGHT, GLYPH_WIDTH,
};
use crate::framebuffer::Framebuffer;
use std::collections::HashMap;
use tb_core::{Color, Rect};

/// The glyph set.
pub struct Font {
    extras: HashMap<char, [u8; 7]>,
}

impl Font {
    fn new() -> Font {
        Font {
            extras: EXTRA.iter().cloned().collect(),
        }
    }

    /// The single built-in font.
    pub fn system() -> &'static Font {
        use std::sync::OnceLock;
        static FONT: OnceLock<Font> = OnceLock::new();
        FONT.get_or_init(Font::new)
    }

    /// 7 rows of 5 pixels, or `None` for characters we do not have.
    pub fn rows(&self, c: char) -> Option<&[u8; 7]> {
        let code = c as u32;
        if (ASCII_START as u32..=0x7E).contains(&code) {
            return Some(&ASCII[(code - ASCII_START as u32) as usize]);
        }
        self.extras.get(&c)
    }

    /// Integer scale for a CSS font size (`px`).
    pub fn scale(&self, size: f32) -> u32 {
        let s = (size / GLYPH_HEIGHT as f32).round();
        if s.is_finite() {
            (s as i32).clamp(1, 6) as u32
        } else {
            1
        }
    }

    /// Pixel advance of one character (glyph + 1 px side bearing per scale).
    pub fn advance(&self, size: f32) -> f32 {
        ((GLYPH_WIDTH + 1) * self.scale(size) as usize) as f32
    }

    pub fn ascent(&self, size: f32) -> f32 {
        (ASCENT_ROWS * self.scale(size) as usize) as f32
    }

    pub fn descent(&self, size: f32) -> f32 {
        (DESCENT_ROWS * self.scale(size) as usize) as f32
    }

    /// Height of one text line (glyph box plus the descender row gap).
    pub fn line_height(&self, size: f32) -> f32 {
        ((GLYPH_HEIGHT + 1) * self.scale(size) as usize) as f32
    }

    /// Width of `text` when drawn at `size`.
    pub fn text_width(&self, text: &str, size: f32, bold: bool, letter_spacing: f32) -> f32 {
        let scale = self.scale(size) as f32;
        let adv = (GLYPH_WIDTH + 1) as f32 * scale + letter_spacing;
        let mut w = 0.0;
        for c in text.chars() {
            if c == '\t' {
                w += adv * 4.0;
                continue;
            }
            w += adv;
            if bold {
                w += scale as f32 * 0.5;
            }
        }
        w
    }

    /// Width of the widest word in `text` — layout uses it to decide whether an
    /// overflowing word has to be broken.
    pub fn longest_word(&self, text: &str, size: f32, bold: bool, letter_spacing: f32) -> f32 {
        text.split_whitespace()
            .map(|w| self.text_width(w, size, bold, letter_spacing))
            .fold(0.0f32, f32::max)
    }

    /// Draw `text` with its baseline at `baseline`; returns the advance.
    ///
    /// `x`/`baseline` are rounded to device pixels. Bold is synthesised by
    /// thickening each pixel one column to the right (the classic trick).
    pub fn draw(
        &self,
        fb: &mut Framebuffer,
        x: f32,
        baseline: f32,
        text: &str,
        size: f32,
        bold: bool,
        color: Color,
        clip: Option<Rect>,
    ) -> f32 {
        let scale = self.scale(size);
        let mut pen_x = x.round() as i32;
        let top = (baseline.round() as i32) - self.ascent(size) as i32;
        for c in text.chars() {
            let adv = ((GLYPH_WIDTH + 1) * scale as usize) as i32;
            if c == '\t' {
                pen_x += adv * 4;
                continue;
            }
            if c != ' ' {
                if let Some(rows) = self.rows(c) {
                    self.draw_glyph(fb, pen_x, top, rows, scale, bold, color, clip);
                }
            }
            pen_x += adv;
        }
        (pen_x - x.round() as i32) as f32
    }

    /// Draw `text` with letter spacing (used for `letter-spacing`, headings).
    pub fn draw_spaced(
        &self,
        fb: &mut Framebuffer,
        x: f32,
        baseline: f32,
        text: &str,
        size: f32,
        bold: bool,
        letter_spacing: f32,
        color: Color,
        clip: Option<Rect>,
    ) -> f32 {
        let scale = self.scale(size);
        let mut pen_x = x.round() as i32;
        let top = baseline.round() as i32 - self.ascent(size) as i32;
        let extra = letter_spacing.round() as i32;
        for c in text.chars() {
            let adv = ((GLYPH_WIDTH + 1) * scale as usize) as i32 + extra;
            if c == '\t' {
                pen_x += adv * 4;
                continue;
            }
            if c != ' ' {
                if let Some(rows) = self.rows(c) {
                    self.draw_glyph(fb, pen_x, top, rows, scale, bold, color, clip);
                }
            }
            pen_x += adv;
        }
        (pen_x - x.round() as i32) as f32
    }

    fn draw_glyph(
        &self,
        fb: &mut Framebuffer,
        x: i32,
        y: i32,
        rows: &[u8; 7],
        scale: u32,
        bold: bool,
        color: Color,
        clip: Option<Rect>,
    ) {
        for (ry, bits) in rows.iter().enumerate() {
            if *bits == 0 {
                continue;
            }
            for cx in 0..GLYPH_WIDTH {
                if bits & (1 << (4 - cx)) == 0 {
                    continue;
                }
                let px = x + (cx * scale as usize) as i32;
                let py = y + (ry * scale as usize) as i32;
                for dy in 0..scale as i32 {
                    for dx in 0..scale as i32 {
                        let (x, y) = (px + dx, py + dy);
                        if let Some(clip) = clip {
                            if !clip.contains(tb_core::Point::new(x as f32 + 0.5, y as f32 + 0.5)) {
                                continue;
                            }
                        }
                        fb.blend_at(x, y, color);
                        if bold && dx + 1 < scale as i32 {
                            fb.blend_at(x + 1, y, color);
                        }
                    }
                }
            }
        }
    }

    /// All characters of `text` we cannot draw (diagnostics / tests).
    pub fn missing(&self, text: &str) -> Vec<char> {
        let mut out: Vec<char> = Vec::new();
        for c in text.chars() {
            if !c.is_control() && c != ' ' && self.rows(c).is_none() && !out.contains(&c) {
                out.push(c);
            }
        }
        out
    }
}

/// Metrics used by the layout engine; mirrors [`Font`] but as free functions so
/// `tb-layout` does not need to know about the `Font` object.
pub fn metrics(size: f32) -> (f32, f32, f32) {
    let f = Font::system();
    (f.ascent(size), f.descent(size), f.line_height(size))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii_is_complete_and_printable() {
        let f = Font::system();
        for code in 0x20..=0x7E_u32 {
            let c = char::from_u32(code).unwrap();
            assert!(f.rows(c).is_some(), "missing glyph {c:?}");
        }
        // every non-space glyph must have at least one painted pixel
        for code in 0x21..=0x7E_u32 {
            let c = char::from_u32(code).unwrap();
            let rows = f.rows(c).unwrap();
            assert!(rows.iter().any(|r| *r != 0), "blank glyph {c:?}");
        }
    }

    #[test]
    fn german_and_typo_extras_exist() {
        let f = Font::system();
        for c in "äöüÄÖÜß€–—…“”‘’•×".chars() {
            assert!(f.rows(c).is_some(), "missing {c:?}");
        }
    }

    #[test]
    fn scale_ladder() {
        let f = Font::system();
        assert_eq!(f.scale(8.0), 1);
        assert_eq!(f.scale(14.0), 2);
        assert_eq!(f.scale(16.0), 2);
        assert_eq!(f.scale(24.0), 3);
        assert_eq!(f.scale(400.0), 6, "clamped");
        assert_eq!(f.scale(0.0), 1);
        assert_eq!(f.scale(f32::NAN), 1);
        assert_eq!(f.line_height(16.0), 16.0);
        assert_eq!(f.ascent(16.0), 12.0);
        assert_eq!(f.descent(16.0), 2.0);
    }

    #[test]
    fn text_width_matches_advance() {
        let f = Font::system();
        let mut fb = Framebuffer::new(200, 20);
        let w = f.text_width("Hallo", 16.0, false, 0.0);
        let adv = f.draw(&mut fb, 0.0, 14.0, "Hallo", 16.0, false, Color::BLACK, None);
        assert_eq!(w, adv);
        assert!(f.text_width("Hallo", 16.0, true, 0.0) > w, "bold is wider");
        assert_eq!(f.text_width("", 16.0, false, 0.0), 0.0);
        assert!(f.text_width("Hallo Welt", 16.0, false, 2.0) > w);
    }

    #[test]
    fn glyphs_paint_pixels_at_the_right_place() {
        let f = Font::system();
        let mut fb = Framebuffer::new(40, 20);
        fb.clear(Color::WHITE);
        // 'I' at scale 1: top row is .###. → x=1..3 painted at y = baseline-6
        f.draw(&mut fb, 0.0, 8.0, "I", 7.0, false, Color::BLACK, None);
        assert_eq!(fb.get(1, 2), Color::BLACK);
        assert_eq!(fb.get(2, 2), Color::BLACK);
        assert_eq!(fb.get(3, 2), Color::BLACK);
        assert_eq!(fb.get(0, 2), Color::WHITE);
        assert_eq!(fb.get(2, 8), Color::BLACK, "baseline row of the stem");
    }

    #[test]
    fn clip_stops_the_glyph() {
        let f = Font::system();
        let mut fb = Framebuffer::new(40, 20);
        fb.clear(Color::WHITE);
        let clip = Rect::new(0.0, 0.0, 2.0, 20.0);
        f.draw(
            &mut fb,
            0.0,
            8.0,
            "WW",
            7.0,
            false,
            Color::BLACK,
            Some(clip),
        );
        assert_eq!(fb.get(10, 4), Color::WHITE, "text outside the clip is gone");
        // 'W' row 3 starts at x=0, which is still inside the 2px clip
        assert_eq!(fb.get(0, 4), Color::BLACK);
    }

    #[test]
    fn missing_characters_are_reported() {
        let f = Font::system();
        assert!(f.missing("normal text").is_empty());
        let m = f.missing("日本");
        assert_eq!(m, vec!['日', '本']);
    }

    #[test]
    fn longest_word_is_used_for_breaking() {
        let f = Font::system();
        let w = f.longest_word("kurz Riesenwort kurz", 14.0, false, 0.0);
        assert_eq!(w, f.text_width("Riesenwort", 14.0, false, 0.0));
    }
}
